import * as XLSX from 'xlsx';
import { paymentTimeZone } from "@/lib/payment-time";
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import type { TariffReport, MeterBreakdown } from '@/../api/reports.api';

/* =============================================================================
 * ALVER POWER SYSTEMS — Report Export Utilities (PDF / Excel / CSV)
 * =============================================================================
 * All three exports share ONE revenue-breakdown calculation
 * (computeRevenueBreakdown) so Gross / Service Charge / Payable always match
 * across every format and the on-screen view. Previously the Excel sheet used
 * a different formula than the PDF/CSV/screen and could show a different
 * number to the client for the same report — that inconsistency is now fixed.
 * ========================================================================= */

// Base64-encoded company logo, embedded so PDF generation has no external
// asset/network dependency at build time.
const LOGO_BASE64 = "data:image/png;base64,";

// The reference rate used to derive the service charge percentage.
// e.g. at BASE_PRICE_PER_UNIT = 28 and a tariff rate of 30.24, the service
// charge is (30.24 - 28) / 28 = 8% of gross revenue.
const BASE_PRICE_PER_UNIT = 28;

// ─── Theme Constants (shared visual language across PDF & Excel) ───────────
const THEME = {
  primary: '#2563eb',
  primaryLight: '#dbeafe',
  primaryDark: '#1d4ed8',
  emerald: '#059669',
  emeraldLight: '#d1fae5',
  amber: '#d97706',
  amberLight: '#fef3c7',
  rose: '#e11d48',
  roseLight: '#ffe4e6',
  violet: '#6d28d9',
  violetLight: '#f5f3ff',
  gray50: '#f8fafc',
  gray100: '#f1f5f9',
  gray200: '#e2e8f0',
  gray400: '#94a3b8',
  gray500: '#64748b',
  gray700: '#334155',
  gray900: '#0f172a',
  white: '#ffffff',
};

// PDF-only RGB triples (jsPDF wants numeric channels, not hex strings)
const PDF_COLOR = {
  primary: [37, 99, 235] as [number, number, number],
  primaryDark: [29, 78, 216] as [number, number, number],
  emerald: [5, 150, 105] as [number, number, number],
  emeraldBg: [240, 253, 244] as [number, number, number],
  amber: [217, 119, 6] as [number, number, number],
  amberBg: [255, 251, 235] as [number, number, number],
  rose: [225, 29, 72] as [number, number, number],
  roseBg: [255, 241, 242] as [number, number, number],
  violet: [109, 40, 217] as [number, number, number],
  violetBg: [245, 243, 255] as [number, number, number],
  blueBg: [239, 246, 255] as [number, number, number],
  ink: [15, 23, 42] as [number, number, number],
  slate: [100, 116, 139] as [number, number, number],
  border: [226, 232, 240] as [number, number, number],
  white: [255, 255, 255] as [number, number, number],
};

const PAGE_MARGIN = 14;

// ─── Formatters ───────────────────────────────────────────────────────────────
const fmt = (n: number) =>
  new Intl.NumberFormat('en-KE', { style: 'currency', currency: 'KES' }).format(n);

const fmtNum = (n: number) => new Intl.NumberFormat('en-KE').format(n);

const fmtDate = (dateString: string, timeZone?: string) =>
  new Date(dateString).toLocaleDateString('en-KE', {
    year: 'numeric', month: 'short', day: 'numeric',
    hour: '2-digit', minute: '2-digit', timeZone,
  });

const fmtDateShort = (dateString: string) =>
  new Date(dateString).toLocaleDateString('en-KE', {
    year: 'numeric', month: 'short', day: 'numeric',
  });

function getDateRange(report: TariffReport): string {
  const { startDate, endDate } = report.dateRange;
  if (startDate && endDate) return `${fmtDateShort(startDate)} – ${fmtDateShort(endDate)}`;
  if (startDate) return `From ${fmtDateShort(startDate)}`;
  if (endDate) return `Until ${fmtDateShort(endDate)}`;
  return 'All Time';
}

/**
 * Single source of truth for the revenue split. Every export (PDF, Excel,
 * CSV) and the on-screen RevenueBreakdown component should call this so the
 * numbers a client sees are always identical no matter which format they open.
 */
function computeRevenueBreakdown(report: TariffReport, basePrice: number = BASE_PRICE_PER_UNIT) {
  const rate = report.tariff.ratePerUnit;
  const servicePercent = basePrice > 0 ? (rate - basePrice) / basePrice : 0;
  const serviceCharge = servicePercent * report.summary.totalRevenue;
  const payable = report.summary.totalRevenue - serviceCharge;
  return { rate, servicePercent, serviceCharge, payable };
}

function pct(part: number, whole: number) {
  if (!whole) return 0;
  return Math.max(0, Math.min(100, (part / whole) * 100));
}

// =============================================================================
// PDF EXPORT — jsPDF, one-click download (no print dialog / popup blockers)
// =============================================================================

type MetaItem = { label: string; value: string };

function drawHeader(doc: jsPDF, title: string, subtitle: string, meta: MetaItem[]): number {
  const pageWidth = doc.internal.pageSize.getWidth();
  const bannerHeight = 40;

  doc.setFillColor(...PDF_COLOR.primary);
  doc.rect(0, 0, pageWidth, bannerHeight, 'F');

  try {
    doc.addImage(LOGO_BASE64, 'PNG', PAGE_MARGIN, 7, 16, 16);
  } catch {
    // Silently continue if the logo ever fails to decode.
  }

  doc.setTextColor(...PDF_COLOR.white);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(14);
  doc.text('Alver Power Systems', PAGE_MARGIN + 20, 13);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.setTextColor(191, 219, 254);
  doc.text('SMART METERING & ENERGY MANAGEMENT', PAGE_MARGIN + 20, 18);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(16);
  doc.setTextColor(...PDF_COLOR.white);
  doc.text(title, pageWidth - PAGE_MARGIN, 14, { align: 'right' });

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.setTextColor(191, 219, 254);
  doc.text(subtitle, pageWidth - PAGE_MARGIN, 19, { align: 'right' });

  const chipY = 30;
  const chipWidth = (pageWidth - PAGE_MARGIN * 2) / meta.length;
  meta.forEach((item, i) => {
    const x = PAGE_MARGIN + i * chipWidth;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(191, 219, 254);
    doc.text(item.label.toUpperCase(), x, chipY);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9.5);
    doc.setTextColor(...PDF_COLOR.white);
    doc.text(item.value, x, chipY + 5);
  });

  doc.setTextColor(...PDF_COLOR.ink);
  return bannerHeight + 10;
}

function drawFooter(doc: jsPDF, footerRight: string) {
  const pageCount = doc.getNumberOfPages();
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();

  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setDrawColor(...PDF_COLOR.border);
    doc.line(PAGE_MARGIN, pageHeight - 15, pageWidth - PAGE_MARGIN, pageHeight - 15);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(...PDF_COLOR.slate);
    doc.text('Alver Power Systems — Confidential · For internal and authorized use only', PAGE_MARGIN, pageHeight - 10);

    doc.text(footerRight, pageWidth - PAGE_MARGIN, pageHeight - 10, { align: 'right' });
    doc.text(`Page ${i} of ${pageCount}`, pageWidth / 2, pageHeight - 10, { align: 'center' });
  }
}

function sectionTitle(doc: jsPDF, text: string, y: number): number {
  doc.setFillColor(...PDF_COLOR.primary);
  doc.rect(PAGE_MARGIN, y - 3.2, 1.2, 4.2, 'F');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10.5);
  doc.setTextColor(...PDF_COLOR.ink);
  doc.text(text.toUpperCase(), PAGE_MARGIN + 3, y);
  return y + 8;
}

type MetricColor = 'blue' | 'green' | 'amber' | 'violet';
type Metric = { label: string; value: string; caption?: string; color: MetricColor };

const METRIC_COLORS: Record<MetricColor, { fg: [number, number, number]; bg: [number, number, number] }> = {
  blue: { fg: PDF_COLOR.primary, bg: PDF_COLOR.blueBg },
  green: { fg: PDF_COLOR.emerald, bg: PDF_COLOR.emeraldBg },
  amber: { fg: PDF_COLOR.amber, bg: PDF_COLOR.amberBg },
  violet: { fg: PDF_COLOR.violet, bg: PDF_COLOR.violetBg },
};

function drawMetricCards(doc: jsPDF, y: number, metrics: Metric[]): number {
  const pageWidth = doc.internal.pageSize.getWidth();
  const gap = 4;
  const cardWidth = (pageWidth - PAGE_MARGIN * 2 - gap * (metrics.length - 1)) / metrics.length;
  const cardHeight = 22;

  metrics.forEach((m, i) => {
    const x = PAGE_MARGIN + i * (cardWidth + gap);
    const colors = METRIC_COLORS[m.color];

    doc.setFillColor(...colors.bg);
    doc.roundedRect(x, y, cardWidth, cardHeight, 2, 2, 'F');

    doc.setFillColor(...colors.fg);
    doc.circle(x + 5, y + 5.5, 1.1, 'F');

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(6.8);
    doc.setTextColor(...PDF_COLOR.slate);
    doc.text(m.label.toUpperCase(), x + 8, y + 6.3);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(13);
    doc.setTextColor(...colors.fg);
    doc.text(m.value, x + 4, y + 15);

    if (m.caption) {
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(6.3);
      doc.setTextColor(...PDF_COLOR.slate);
      doc.text(m.caption, x + 4, y + 19.5);
    }
  });

  return y + cardHeight + 10;
}

type BreakdownRow = { label: string; value: string; amount: number; color: [number, number, number] };

function drawProportionalBreakdown(doc: jsPDF, y: number, rows: BreakdownRow[], total: number): number {
  const pageWidth = doc.internal.pageSize.getWidth();
  const contentWidth = pageWidth - PAGE_MARGIN * 2;
  const colWidth = contentWidth / rows.length;

  rows.forEach((row, i) => {
    const x = PAGE_MARGIN + i * colWidth;

    doc.setFillColor(...row.color);
    doc.circle(x + 1.5, y - 3, 1, 'F');

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(...PDF_COLOR.slate);
    doc.text(row.label.toUpperCase(), x + 4.5, y - 2.3);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11.5);
    doc.setTextColor(...PDF_COLOR.ink);
    doc.text(row.value, x, y + 4);

    const barWidth = colWidth - 6;
    doc.setFillColor(...PDF_COLOR.border);
    doc.roundedRect(x, y + 7, barWidth, 1.6, 0.8, 0.8, 'F');
    doc.setFillColor(...row.color);
    doc.roundedRect(x, y + 7, Math.max(2, (barWidth * pct(row.amount, total)) / 100), 1.6, 0.8, 0.8, 'F');

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(6.5);
    doc.setTextColor(...PDF_COLOR.slate);
    doc.text(`${pct(row.amount, total).toFixed(1)}% of gross`, x, y + 12);
  });

  return y + 20;
}

function styledTable(
  doc: jsPDF,
  startY: number,
  head: string[][],
  body: (string | number)[][],
  columnStyles?: Record<number, any>
) {
  autoTable(doc, {
    head,
    body,
    startY,
    margin: { left: PAGE_MARGIN, right: PAGE_MARGIN },
    styles: {
      font: 'helvetica',
      fontSize: 8.5,
      cellPadding: 3,
      textColor: PDF_COLOR.ink,
      lineColor: PDF_COLOR.border,
      lineWidth: 0.1,
    },
    headStyles: {
      fillColor: PDF_COLOR.primary,
      textColor: PDF_COLOR.white,
      fontStyle: 'bold',
      fontSize: 8,
    },
    alternateRowStyles: {
      fillColor: [248, 250, 252],
    },
    columnStyles,
  });
  // @ts-ignore - jspdf-autotable attaches this to the doc instance
  return doc.lastAutoTable.finalY as number;
}

export function generateTariffReportPDF(report: TariffReport): void {
  const doc = new jsPDF();
  const dateRange = getDateRange(report);
  const { rate, serviceCharge, payable } = computeRevenueBreakdown(report);
  const grossRevenue = report.summary.totalRevenue;

  let y = drawHeader(doc, 'Tariff Report', `Generated on ${new Date().toLocaleString('en-KE')}`, [
    { label: 'Tariff', value: report.tariff.name },
    { label: 'Provider', value: report.tariff.provider },
    { label: 'Rate / Unit', value: fmt(rate) },
    { label: 'Period', value: dateRange },
  ]);

  y = sectionTitle(doc, 'Key Metrics', y);
  y = drawMetricCards(doc, y, [
    { label: 'Total Meters', value: fmtNum(report.summary.totalMeters), caption: 'Active in period', color: 'blue' },
    { label: 'Transactions', value: fmtNum(report.summary.totalTransactions), caption: 'Completed', color: 'green' },
    { label: 'Total Units (kWh)', value: report.summary.totalUnits.toFixed(1), caption: 'Energy dispensed', color: 'amber' },
    { label: 'Gross Revenue', value: fmt(grossRevenue), caption: 'Before deductions', color: 'violet' },
  ]);

  y = sectionTitle(doc, 'Revenue Breakdown', y);
  y = drawProportionalBreakdown(
    doc,
    y + 6,
    [
      { label: 'Gross Revenue', value: fmt(grossRevenue), amount: grossRevenue, color: PDF_COLOR.violet },
      { label: 'Service Charge', value: fmt(serviceCharge), amount: serviceCharge, color: PDF_COLOR.rose },
      { label: 'Payable to Client', value: fmt(payable), amount: payable, color: PDF_COLOR.emerald },
    ],
    grossRevenue
  );

  if (report.meterBreakdown.length > 0) {
    const sorted = [...report.meterBreakdown].sort((a, b) => b.totalRevenue - a.totalRevenue);
    const totalTxns = sorted.reduce((s, m) => s + m.transactionCount, 0);
    const totalUnits = sorted.reduce((s, m) => s + m.totalUnits, 0);
    const totalRev = sorted.reduce((s, m) => s + m.totalRevenue, 0);

    y = sectionTitle(doc, `Meter Breakdown (${sorted.length} meters)`, y);
    styledTable(
      doc,
      y,
      [['Meter Number', 'Transactions', 'Units (kWh)', 'Revenue']],
      [
        ...sorted.map((m: MeterBreakdown) => [
          m.meterNumber,
          fmtNum(m.transactionCount),
          m?.totalUnits?.toFixed(2),
          fmt(m.totalRevenue),
        ]),
        ['Totals', fmtNum(totalTxns), totalUnits.toFixed(2), fmt(totalRev)],
      ],
      { 0: { fontStyle: 'bold' } }
    );
  }

  drawFooter(doc, `Tariff: ${report.tariff.name} · ${dateRange}`);

  const tariffName = report.tariff.name.replace(/[^a-zA-Z0-9]/g, '_');
  const rangeSuffix = dateRange.replace(/[^a-zA-Z0-9]/g, '_');
  doc.save(`Alver_Tariff_Report_${tariffName}_${rangeSuffix}.pdf`);
}

